int mtu = 1500;
int ipHeader = 20;
int originalIpPayload = 2000; // includes upper-layer header
int firstData = ((mtu - ipHeader) / 8) * 8;
int lastData = originalIpPayload - firstData;
Console.WriteLine($"first total={firstData+ipHeader} offset=0 MF=1");
Console.WriteLine($"last total={lastData+ipHeader} offset={firstData/8} MF=0");
// 1500 -> 1480+20; second 520+20, offset 185
// 1400 -> 1376+20; second 624+20, offset 172

